rule "uddi_normalize_dns_fields"
when
  has_field("event_class_id") && has_field("InfobloxDNSRCode")
then
  let rc = to_string($message.InfobloxDNSRCode);
  set_field("dns_event_type", "response");
  set_field("rcode", rc);
  set_field("qname", to_string($message.destinationDnsDomain));
  set_field("qtype", to_string($message.InfobloxDNSQType));
  set_field("dns_is_nxdomain", rc == "NXDOMAIN");
  set_field("dns_is_servfail", rc == "SERVFAIL");
  set_field("dns_is_error",    rc != "NOERROR" && rc != "");
end
